# El banco de pruebas: una página (salida/banco.html) con las figuras del lote, para las hojas de revisión y las comprobaciones
# (hoja.py, numeros.py, verifica.py, saltos.py). Antes: node datos.mjs
HEAD = '<!DOCTYPE html><html><head><meta charset="utf-8"><style>body{margin:0;background:#000;color:#ccd;font:12px Inter,sans-serif}\n.g{display:grid;gap:6px;padding:6px}.c{background:radial-gradient(120% 90% at 50% 0,#262a3e,#0c0d12 78%);border-radius:10px;position:relative}\n.c svg{display:block}.sd g[transform],.sd .pl{opacity:.12}.c b{position:absolute;left:6px;top:4px;font-weight:600;color:#dfe2ee}.c i{position:absolute;right:6px;top:4px;color:#8a90a8;font-style:normal}</style></head>\n<body><svg width="0" height="0" style="position:absolute"><defs id="defs"></defs></svg><div id="out"></div>\n'
TAIL = '<script src="../../../src/fig3d/fig3d.js"></script><script src="../../../src/fig3d/gear3d.js"></script><script src="../../../src/fig3d/mov3d.js"></script><script src="../../../src/fig3d/tiron3d.js"></script><script src="../../../src/fig3d/piernas3d.js"></script><script src="../../../src/fig3d/brazos3d.js"></script><script src="../../../src/fig3d/hombros3d.js"></script><script src="../../../src/fig3d/core3d.js"></script><script src="../../../src/fig3d/funcional3d.js"></script><script src="../../../src/fig3d/cardio3d.js"></script>\n<script>\ndocument.getElementById(\'defs\').innerHTML = Fig3D.DEFS;\nconst EXS = {};\nfor (const e of LOTE) { const x = Fig3D.make(e.n, e.w, e.p, e.s); if (x) EXS[e.n] = x; }\n/* el encuadre: lo que ocupa el gesto entero (sin lo que se sale a propósito) */\nconst tmp = document.createElementNS(\'http://www.w3.org/2000/svg\', \'svg\');\ntmp.setAttribute(\'width\', 0); tmp.setAttribute(\'height\', 0); tmp.style.position = \'absolute\'; document.body.appendChild(tmp);\nconst boxOf = (ex, cam, ts) => {\n  let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;\n  for (const t of ts) {\n    tmp.innerHTML = Fig3D.draw(ex, t, cam, \'z\');\n    for (const el of tmp.children) { if (el.tagName == \'defs\' || el.classList.contains(\'nf\')) continue; const b = el.getBBox(); if (!b.width && !b.height) continue; x0 = Math.min(x0, b.x); y0 = Math.min(y0, b.y); x1 = Math.max(x1, b.x + b.width); y1 = Math.max(y1, b.y + b.height); }\n  }\n  return [x0, y0, x1 - x0, y1 - y0];\n};\nconst fit = (b, A = 1, m = .06) => { let [x, y, w, h] = b; const k = m * Math.max(w, h); x -= k; y -= k; w += 2 * k; h += 2 * k; if (w / h < A) { const nw = h * A; x -= (nw - w) / 2; w = nw; } else { const nh = w / A; y -= (nh - h) / 2; h = nh; } return [x, y, w, h]; };\nwindow.sheet = (names, cols, size) => {\n  const out = document.getElementById(\'out\');\n  out.innerHTML = \'\';\n  const g = document.createElement(\'div\'); g.className = \'g\'; g.style.gridTemplateColumns = `repeat(${cols.length}, ${size}px)`; out.appendChild(g);\n  let n = 0;\n  for (const name of names) {\n    const ex = EXS[name];\n    for (const [t, view] of cols) {\n      const yaw = view == \'cam\' ? ex.yaw : view == \'side\' ? (ex.side ? ex.side[0] : -72) : view == \'front\' ? 0 : view;\n      const pitch = view == \'cam\' ? ex.pitch : view == \'side\' ? (ex.side ? ex.side[1] : 0) : 6;\n      const cam = Fig3D.camera(yaw, pitch);\n      const vb = fit(boxOf(ex, cam, [0, .25, .5, .75, 1]));\n      const c = document.createElement(\'div\'); c.className = \'c\' + (view == \'side\' ? \' sd\' : \'\');\n      c.innerHTML = `<svg width="${size}" height="${size}" viewBox="${vb.map(v => v.toFixed(1)).join(\' \')}">${Fig3D.draw(ex, t, cam, \'k\' + (n++))}</svg>` + (view == \'cam\' && t == cols[0][0] ? `<b>${name}</b>` : \'\') + `<i>${view == \'cam\' ? \'\' : view} ${t}</i>`;\n      g.appendChild(c);\n    }\n  }\n};\n</script></body></html>'
MAP = open('salida/mapa.json').read()
REG = open('salida/regiones.txt').read().strip()
LOTE = open('salida/lote.json').read()
open('salida/banco.html', 'w').write(HEAD + '<script>window.FIG_MAP = ' + MAP + '; window.FIG_REG = ' + REG + '; window.LOTE = ' + LOTE + ';</script>\n' + TAIL)
print('salida/banco.html')
